import random
import string

def generate_password(length=12, include_special=True):
    characters = string.ascii_letters + string.digits + string.punctuation
    if include_special:
        characters += string.punctuation
    return ''.join(random.choice(characters) for _ in range(length))

def is_anagram_phrase(phrase1, phrase2):
    phrase1 = phrase1.replace(" ", "").replace(",", "").replace(".", "").lower()
    phrase2 = phrase2.replace(" ", "").replace(",", "").replace(".", "").lower()
    return sorted(phrase1) == sorted(phrase2)

def main():
    password = generate_password()
    print(f"Generated password: {password}")

    phrases = ['school master', 'the classroom']
    for phrase1, phrase2 in zip(phrases, phrases):
        if is_anagram_phrase(phrase1, phrase2):
            print(f"'{phrase1}' and '{phrase2}' are anagrams of each other.")

if __name__ == "__main__":
    main()

