def integrate(function, start_x, end_x, method='trapezoid'):
    if method == 'trapezoid':
        return quad(function, start_x, end_x, args=(0,))
    elif method == 'simpson':
        return quad(function, start_x, end_x, args=(0,))
    else:
        raise ValueError("Invalid method. Choose 'trapezoid' or 'simpson'.")

